    if (nums == null || nums.length == 0) return result;
    boolean[] used = new boolean[nums.length];
    List<Integer> permutation = new ArrayList<>();
    backtrack(nums, used, permutation, result);
    return result;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> permutation, List<List<Integer>> result) {
    if (permutation.size() == nums.length) {
        result.add(new ArrayList<>(permutation));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        permutation.add(nums[i]);
        backtrack(nums, used, permutation, result);
        permutation.remove(permutation.size() - 1);
        used[i] = false;
    }
}

public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;

    if (strings == null || strings.isEmpty()) {
        return maxLength;
    }

    // Start with the first string and check all its substrings
    String firstString = strings.get(0);
    int length = firstString.length();

    // Generate all substrings of the first string
    for (int start = 0; start < length; start++) {
        for (int end = start + 1; end <= length; end++) {
            String substring = firstString.substring(start, end);
            String inverseSubstring = new StringBuilder(substring).reverse().toString();

            boolean allContain = true;
            for (String str : strings) {
                if (!str.contains(substring) && !str.contains(inverseSubstring)) {
                    allContain = false;
                    break;
                }
            }

            if (allContain) {
                maxLength = Math.max(maxLength, substring.length());
            }
        }
    }

    return maxLength;
}

