public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int depositCount = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                markDeposit(grid, visited, i, j);
                depositCount++;
            }
        }
    }

    return depositCount;
}

private static void markDeposit(char[][] grid, boolean[][] visited, int row, int col) {
    int[] rowDirections = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] colDirections = {-1, 0, 1, -1, 1, -1, 0, 1};

    visited[row][col] = true;

    for (int d = 0; d < 8; d++) {
        int newRow = row + rowDirections[d];
        int newCol = col + colDirections[d];

        if (isValid(grid, visited, newRow, newCol)) {
            markDeposit(grid, visited, newRow, newCol);
        }
    }
}

private static boolean isValid(char[][] grid, boolean[][] visited, int row, int col) {
    return row >= 0 && row < grid.length && col >= 0 && col < grid[row].length
            && grid[row][col] == '@' && !visited[row][col];
}

