private static void markOilDeposit(char[][] grid, int row, int col) {
    if (row < 0 || col < 0 || row >= grid.length || col >= grid[0].length || grid[row][col] != '@') {
        return;
    }

    grid[row][col] = '*'; // Mark the oil pocket as visited

    // Explore all 8 possible directions
    int[] rowDirections = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] colDirections = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int k = 0; k < 8; k++) {
        markOilDeposit(grid, row + rowDirections[k], col + colDirections[k]);
    }
}

