public static int maxRegions(int N) {
    if (N == 0) return 1; // No triangles, just the plane itself
    if (N == 1) return 2; // One triangle divides the plane into 2 regions

    // The formula to calculate the maximum number of regions for N triangles
    // can be derived from the fact that each new triangle can intersect all the
    // previous triangles, creating new regions.
    // The formula is: R(N) = R(N-1) + 2 * (N-1)
    // Starting with R(0) = 1 and R(1) = 2
    int regions = 2; // Starting with one triangle
    for (int i = 2; i <= N; i++) {
        regions = regions + 2 * (i - 1);
    }
    return regions;
}

public static int maxRegions(int N) {
    if (N == 0) return 1;
    if (N == 1) return 2;
    int[] regions = new int[N + 1];
    regions[0] = 1;
    regions[1] = 2;
    for (int i = 2; i <= N; i++) {
        regions[i] = regions[i - 1] + 3 * (i - 1);
    }
    return regions[N];
}

