public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    return canTravelUtil(start[0], start[1], end, paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelUtil(int x, int y, int[] end, int[][] paths, boolean[][] visited) {
    if (x == end[0] && y == end[1]) {
        return true;
    }
    visited[x][y] = true;
    for (int[] path : paths) {
        if (path[0] == x && path[1] == y) {
            if (!visited[path[2]][path[3]] && canTravelUtil(path[2], path[3], end, paths, visited)) {
                return true;
            }
        } else if (path[2] == x && path[3] == y) {
            if (!visited[path[0]][path[1]] && canTravelUtil(path[0], path[1], end, paths, visited)) {
                return true;
            }
        }
    }
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    boolean pathExists = dfs(start[0], start[1], end[0], end[1], visited, paths, n);
    return pathExists ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int endX, int endY, boolean[][] visited, int[][] paths, int n) {
    if (x == endX && y == endY) {
        return true;
    }
    if (x < 0 || y < 0 || x >= n || y >= n || visited[x][y]) {
        return false;
    }

    visited[x][y] = true;

    for (int[] path : paths) {
        if ((path[0] == x && path[1] == y) || (path[1] == x && path[0] == y)) {
            if (dfs(path[0] == x ? path[1] : path[0], path[1] == y ? path[0] : path[1], endX, endY, visited, paths, n)) {
                return true;
            }
        }
    }

    visited[x][y] = false;
    return false;
}

