}

private static boolean canTravelRecursive(int currentX, int currentY, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (currentX == endX && currentY == endY) {
        return true;
    }
    visited[currentX][currentY] = true;
    for (int[] path : paths) {
        if (path[0] == currentX && path[1] == currentY && !visited[path[2]][path[3]]) {
            if (canTravelRecursive(path[2], path[3], endX, endY, paths, visited)) {
                return true;
            }
        } else if (path[2] == currentX && path[3] == currentY && !visited[path[0]][path[1]]) {
            if (canTravelRecursive(path[0], path[1], endX, endY, paths, visited)) {
                return true;
            }
        }
    }
    return false;
}

