    boolean isReachable = dfs(start[0], start[1], end[0], end[1], paths, visited);
    return isReachable ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (x < 0 || x >= visited.length || y < 0 || y >= visited[0].length || visited[x][y]) {
        return false;
    }
    if (x == endX && y == endY) {
        return true;
    }
    visited[x][y] = true;

    for (int[] path : paths) {
        if (path[0] == x && path[1] == y) {
            if (dfs(path[2], path[3], endX, endY, paths, visited)) {
                return true;
            }
        } else if (path[2] == x && path[3] == y) {
            if (dfs(path[0], path[1], endX, endY, paths, visited)) {
                return true;
            }
        }
    }
    return false;
}

