public double trimMean(int[] arr) {
    int n = arr.length;
    int trimSize = n / 20;
    double sum = 0;

    // Sort the array
    java.util.Arrays.sort(arr);

    // Calculate the sum of the elements after trimming
    for (int i = trimSize; i < n - trimSize; i++) {
        sum += arr[i];
    }

    // Calculate the mean
    return sum / (n - 2 * trimSize);
}

