public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // Precompute the prefix sums
    double[][] prefixSum = new double[n][n + 1];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= n; j++) {
            prefixSum[i][j] = Double.NaN;
        }
    }

    // Helper function to calculate the prefix sum
    java.util.function.BiFunction<Integer, Integer, Double> getPrefixSum = (start, length) -> {
        if (length == 0) return 0.0;
        if (prefixSum[start][length] != Double.NaN) return prefixSum[start][length];
        double sum = 0;
        for (int i = start; i < start + length; i++) {
            sum += nums[i];
        }
        prefixSum[start][length] = sum;
        return sum;
    };

    // Check for possible partitions
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            if (n * getPrefixSum.apply(0, i) == sum * j) {
                if (checkPartition(nums, i, j, 0, 0, getPrefixSum)) {
                    return true;
                }
            }
        }
    }
    return false;
}

private boolean checkPartition(int[] nums, int subArraySize, int subArrayCount, int start, int currentCount, java.util.function.BiFunction<Integer, Integer, Double> getPrefixSum) {
    if (currentCount == subArrayCount) {
        return true;
    }
    if (start + subArraySize > nums.length) {
        return false;
    }
    double targetSum = getPrefixSum.apply(0, nums.length) * (currentCount + 1) / subArrayCount;
    double currentSum = getPrefixSum.apply(start, subArraySize);
    if (currentSum != targetSum) {
        return checkPartition(nums, subArraySize, subArrayCount, start + 1, currentCount, getPrefixSum);
    } else {
        return checkPartition(nums, subArraySize, subArrayCount, start + subArraySize, currentCount + 1, getPrefixSum) ||
               checkPartition(nums, subArraySize, subArrayCount, start + 1, currentCount, getPrefixSum);
    }
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int n = nums.length;
    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][sum * n / 2 + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        for (int j = Math.min(i, n / 2); j > 0; j--) {
            for (int k = 0; k <= sum * n / 2; k++) {
                dp[i][j][k] = dp[i - 1][j][k];
                if (!dp[i][j][k] && k >= nums[i - 1] * j) {
                    dp[i][j][k] = dp[i - 1][j - 1][k - nums[i - 1] * j];
                }
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        if (sum * j % n == 0 && dp[n][j][sum * j / n]) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    int n = nums.length;
    boolean[][][] dp = new boolean[n + 1][totalSum + 1][n + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= totalSum; j++) {
            for (int k = 0; k <= i; k++) {
                if (dp[i - 1][j][k]) {
                    dp[i][j][k] = true;
                    if (j + nums[i - 1] <= totalSum) {
                        dp[i][j + nums[i - 1]][k + 1] = true;
                    }
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (totalSum * i % n == 0) {
            int sum1 = totalSum * i / n;
            if (dp[n][sum1][i]) {
                return true;
            }
        }
    }

    return false;
}

