            for (int k = 0; k <= sum; k++) {
                dp[i][j][k] = dp[i - 1][j][k];
                if (k >= nums[i - 1]) {
                    dp[i][j][k] |= dp[i - 1][j - 1][k - nums[i - 1]];
                }
            }
        }
