public boolean hasAllCodes(String s, int k) {
    if (s.length() < k * (1 << k)) {
        return false;
    }

    Set<Integer> seen = new HashSet<>();
    int val = 0;
    int mask = (1 << k) - 1;

    for (int i = 0; i < s.length(); i++) {
        val = (val << 1) & mask | (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen.add(val);
        }
    }

    return seen.size() == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
    if (s.length() < (1 << k) + k - 1) {
        return false;
    }

    Set<Integer> seen = new HashSet<>();
    int allOnes = (1 << k) - 1;
    int hash = 0;

    for (int i = 0; i < s.length(); i++) {
        hash = ((hash & allOnes) << 1) + (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen.add(hash);
        }
    }

    return seen.size() == (1 << k);
}

