public int minInsertions(String s) {
    int left = 0, right = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            right += 2;
            if (right % 2 == 1) {
                left++;
                right--;
            }
        } else {
            right--;
            if (right == -1) {
                left++;
                right = 1;
            }
        }
    }
    return left + right;
}

public int minInsertions(String s) {
    int open = 0, insertions = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            open++;
        } else {
            if (open > 0) {
                open--;
            } else {
                insertions++;
            }
        }
    }
    insertions += 2 * open; // For every unmatched '(', we need to add one more ')' and one more '('
    return insertions;
}

public int minInsertions(String s) {
    int open = 0; // To track the number of unmatched '('
    int insertions = 0; // To track the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);
        if (current == '(') {
            open++;
        } else {
            if (open > 0) {
                open--; // Match the current ')' with a previous '('
            } else {
                insertions++; // Need to insert a '(' to match the current ')'
            }
            // Check if we need to insert a ')' to balance the next character which should be a ')'
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next ')' as it is balanced
            } else {
                insertions++; // Need to insert a ')' to balance the current ')'
            }
        }
    }
    // Add the remaining unmatched '('
    insertions += open * 2;
    return insertions;
}

public int minInsertions(String s) {
    int open = 0; // number of open parentheses '('
    int insert = 0; // number of insertions needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            open++;
        } else { // c == ')'
            if (open > 0) {
                open--;
            } else {
                insert++; // need to insert '(' to balance the current ')'
            }
        }
    }

    // every remaining open parenthesis needs a closing brace
    insert += open * 2;

    return insert;
}

public int minInsertions(String s) {
    int open = 0, close = 0;
    int result = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (close > 0) {
                result += open > 0 ? 1 : 2;
                open = Math.max(0, open - 1);
                close = 0;
            }
            open++;
        } else {
            close++;
            if (close == 2) {
                if (open > 0) {
                    open--;
                } else {
                    result++;
                }
                close = 0;
            }
        }
    }
    if (close == 1) {
        result += open > 0 ? 1 : 2;
        open = Math.max(0, open - 1);
    }
    return result + open * 2;
}

