public int maxUniqueSplit(String s) {
    return helper(s, new HashSet<>());
}

private int helper(String s, HashSet<String> set) {
    if (s.isEmpty()) {
        return 0;
    }
    int max = 0;
    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        if (!set.contains(prefix)) {
            set.add(prefix);
            max = Math.max(max, 1 + helper(s.substring(i), set));
            set.remove(prefix);
        }
    }
    return max;
}

public int maxUniqueSplit(String s) {
    return maxUniqueSplitHelper(s, 0, new HashSet<String>());
}

private int maxUniqueSplitHelper(String s, int index, HashSet<String> used) {
    if (index == s.length()) {
        return 0;
    }
    int maxUnique = 0;
    for (int i = index + 1; i <= s.length(); i++) {
        String substring = s.substring(index, i);
        if (!used.contains(substring)) {
            used.add(substring);
            maxUnique = Math.max(maxUnique, 1 + maxUniqueSplitHelper(s, i, used));
            used.remove(substring);
        }
    }
    return maxUnique;
}

