public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    while (n > 0) {
        int minVal = Math.max(1, k - 26 * (n - 1));
        result.append((char) ('a' + minVal - 1));
        k -= minVal;
        n--;
    }
    return result.toString();
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    k -= n; // Adjust k because we will initially fill the array with 'a'
    for (int i = n - 1; i >= 0; i--) {
        if (k > 0) {
            int add = Math.min(k, 25);
            result[i] = (char) ('a' + add);
            k -= add;
        } else {
            result[i] = 'a';
        }
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < n; i++) {
        result.append('a');
        k -= 1;
    }
    for (int i = n - 1; k > 0; i--) {
        int diff = Math.min(25, k);
        result.setCharAt(i, (char) (result.charAt(i) + diff));
        k -= diff;
    }
    return result.toString();
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    k -= n; // Initial value assuming all characters are 'a'
    for (int i = n - 1; i >= 0; i--) {
        int value = Math.min(k, 25); // Can fill at most 'z' (25) per position
        result[i] = (char) ('a' + value);
        k -= value;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int remainingValue = k - n; // Start by assuming all characters are 'a'

    for (int i = n - 1; i >= 0; i--) {
        if (remainingValue > 25) {
            result.append('z'); // Use 'z' if we can't reach the target value with remaining letters
            remainingValue -= 25; // 'z' contributes 26, but we've already counted 1 for 'a'
        } else {
            // Determine the character that, when added to 'a', gives the needed remaining value
            char currentChar = (char) ('a' + remainingValue);
            result.append(currentChar);
            remainingValue = 0; // We've reached the target value
        }
    }

    return result.reverse().toString(); // The string was built backwards
}

