public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    for (int i = 0; i <= 9; i++) {
        if (i >= low) {
            result.add(i);
        }
        findSteppingNumbersHelper(i, i, high, result);
    }
    Collections.sort(result);
    return result;
}

private static void findSteppingNumbersHelper(int prev, long current, int high, List<Integer> result) {
    if (current > high) {
        return;
    }
    if (current >= 10 && current <= high) {
        result.add((int) current);
    }
    int lastDigit = (int) (current % 10);
    if (lastDigit > 0) {
        findSteppingNumbersHelper(lastDigit, current * 10 + lastDigit - 1, high, result);
    }
    if (lastDigit < 9) {
        findSteppingNumbersHelper(lastDigit, current * 10 + lastDigit + 1, high, result);
    }
}

