    }

    int lastDigit = num % 10;

    if (lastDigit > 0) {
        int newNum = num * 10 + (lastDigit - 1);
        if (newNum >= low) {
            result.add(newNum);
        }
        buildSteppingNumbers(newNum, result, low, high);
    }

    if (lastDigit < 9) {
        int newNum = num * 10 + (lastDigit + 1);
        if (newNum >= low) {
            result.add(newNum);
        }
        buildSteppingNumbers(newNum, result, low, high);
    }
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    for (int i = 0; i <= 9; i++) {
        bfs(i, low, high, result);
    }

    Collections.sort(result);
    return result;
}

private static void bfs(int start, int low, int high, List<Integer> result) {
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(start);

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) continue;
        if (num >= low) result.add(num);
        if (num == 0) continue;

        int lastDigit = num % 10;
        int next1 = num * 10 + (lastDigit - 1);
        int next2 = num * 10 + (lastDigit + 1);

        if (lastDigit > 0 && next1 <= high) queue.offer(next1);
        if (lastDigit < 9 && next2 <= high) queue.offer(next2);
    }
}

