                dp[i][j][2] = (i > 0 && j > 0) ? dp[i - 1][j - 1][2] + 1 : 1;
                // Diagonal down-left
                dp[i][j][3] = (i > 0 && j < n - 1) ? dp[i - 1][j + 1][3] + 1 : 1;

                // Update the maximum length
                maxLength = Math.max(maxLength, Math.max(dp[i][j][0], dp[i][j][1]));
