public static int squarePermutations(int[] A) {
    List<Integer> nums = IntStream.of(A).boxed().collect(Collectors.toList());
    boolean[] used = new boolean[nums.size()];
    List<List<Integer>> result = new ArrayList<>();
    backtrack(nums, new ArrayList<>(), used, result);
    return result.size();
}

private static void backtrack(List<Integer> nums, List<Integer> tempList, boolean[] used, List<List<Integer>> result) {
    if (tempList.size() == nums.size()) {
        result.add(new ArrayList<>(tempList));
    } else {
        for (int i = 0; i < nums.size(); i++) {
            if (used[i] || (i > 0 && nums.get(i) == nums.get(i - 1) && !used[i - 1])) continue; // skip duplicates
            if (tempList.isEmpty() || isPerfectSquare(tempList.get(tempList.size() - 1) + nums.get(i))) {
                used[i] = true;
                tempList.add(nums.get(i));
                backtrack(nums, tempList, used, result);
                used[i] = false;
                tempList.remove(tempList.size() - 1);
            }
        }
    }
}

