private static int backtrack(int[] A, boolean[] used, List<Integer> current, int count) {
    if (current.size() == A.length) {
        return 1;
    }

    Set<Integer> seen = new HashSet<>();
    int result = 0;
    for (int i = 0; i < A.length; i++) {
        if (used[i] || seen.contains(A[i])) continue;
        if (current.isEmpty() || isPerfectSquare(current.get(current.size() - 1), A[i])) {
            used[i] = true;
            current.add(A[i]);
            result += backtrack(A, used, current, count + 1);
            current.remove(current.size() - 1);
            used[i] = false;
            seen.add(A[i]);
        }
    }
    return result;
}

