    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;

    // Find the first decreasing element
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such element is found, return -1
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on right side of digits[i] which is greater than digits[i]
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found elements
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the digits after i
    reverse(digits, i + 1, digits.length - 1);

    // Convert the array of digits back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // In case of overflow
    }
}

private static void reverse(char[] array, int left, int right) {
    while (left < right) {
        char temp = array[left];
        array[left] = array[right];
        array[right] = temp;
        left++;
        right--;
    }
}

